func clearTargets(numSlots int) error {
	m, err := ebpf.LoadPinnedMap(targetMapPath(), nil)
	if err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			return nil
		}
		return err
	}
	defer m.Close()

	for i := 0; i < numSlots; i++ {
		key := uint32(i)
		if err := m.Delete(&key); err != nil && !errors.Is(err, ebpf.ErrKeyNotExist) {
			return fmt.Errorf("clear slot %d: %w", i, err)
		}
	}
	return nil
}

func (s *Server) openWorker(idx int) (*net.UDPConn, int, error) {
	attachPolicy := s.policy != nil && s.policy.program != nil && idx == 0
	var attachErr error

	lc := net.ListenConfig{Control: func(network, address string, c syscall.RawConn) error {
		return c.Control(func(fd uintptr) {
			if err := unix.SetsockoptInt(int(fd), unix.SOL_SOCKET, unix.SO_REUSEADDR, 1); err != nil && attachErr == nil {
				attachErr = fmt.Errorf("SO_REUSEADDR: %w", err)
				return
			}
			if err := unix.SetsockoptInt(int(fd), unix.SOL_SOCKET, unix.SO_REUSEPORT, 1); err != nil && attachErr == nil {
				attachErr = fmt.Errorf("SO_REUSEPORT: %w", err)
				return
			}
			if attachPolicy && attachErr == nil {
				if err := s.policy.attach(int(fd)); err != nil {
					attachErr = err
				}
			}
		})
	}}

func buildPayload(rng *rand.Rand, buf []byte, reqType, reqID, prefix string, keySpace, scanLimit int) []byte {
	buf = buf[:0]
	buf = append(buf, reqType...)
	buf = append(buf, ' ')
	keyIdx := rng.Intn(keySpace)
	buf = appendKey(buf, prefix, keyIdx)
	if reqType == "SCAN" {
		buf = append(buf, ' ')
		buf = strconv.AppendInt(buf, int64(scanLimit), 10)
	}
	buf = append(buf, ' ')
	buf = append(buf, reqID...)
	return buf
}

func appendKey(buf []byte, prefix string, keyIdx int) []byte {
	buf = append(buf, prefix...)
	if keyIdx < 100000000 {
		start := len(buf)
		buf = append(buf, '0', '0', '0', '0', '0', '0', '0', '0')
		for i := 7; i >= 0; i-- {
			buf[start+i] = byte('0' + keyIdx%10)
			keyIdx /= 10
		}
		return buf
	}
	return strconv.AppendInt(buf, int64(keyIdx), 10)
}

func makeReqID(sendNano int64, seq uint64, isGet bool) string {
	var buf [idTotalLen]byte
	writeHex(buf[:idTimeHexLen], uint64(sendNano))
	writeHex(buf[idTimeHexLen:idTimeHexLen+idSeqHexLen], seq)
	if isGet {
		buf[idTotalLen-1] = reqTypeGet
	} else {
		buf[idTotalLen-1] = reqTypeScan
	}
	return string(buf[:])
}

func writeHex(dst []byte, value uint64) {
	for i := len(dst) - 1; i >= 0; i-- {
		dst[i] = hexDigits[value&0xF]
		value >>= 4
	}
}

